from pathlib import Path
import ast, json

srcdir = Path('/inputs')
outfile = Path('/work/layout.json')

# Select the bounded set of top-level Python sources.
paths = []
for p in srcdir.iterdir():
    if not p.is_file() or p.suffix != '.py':
        continue
    if p.name == '__init__.py' or p.name.startswith('test_') or p.name.endswith('_test.py'):
        continue
    paths.append(p)
paths.sort(key=lambda p: p.name)

included = {p.stem: p.name for p in paths}
line_counts = {}
graph = {}
package = 'skillc.frontend'

for p in paths:
    text = p.read_text(encoding='utf-8')
    line_counts[p.name] = len(text.splitlines())
    tree = ast.parse(text, filename=str(p))
    targets = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                name = alias.name
                prefix = package + '.'
                if name.startswith(prefix):
                    first = name[len(prefix):].split('.', 1)[0]
                    if first in included:
                        targets.add(included[first])
        elif isinstance(node, ast.ImportFrom):
            if node.level == 1:
                if node.module:
                    first = node.module.split('.', 1)[0]
                    if first in included:
                        targets.add(included[first])
                else:
                    for alias in node.names:
                        if alias.name != '*':
                            first = alias.name.split('.', 1)[0]
                            if first in included:
                                targets.add(included[first])
            elif node.level == 0:
                module = node.module or ''
                if module == package:
                    for alias in node.names:
                        if alias.name != '*':
                            first = alias.name.split('.', 1)[0]
                            if first in included:
                                targets.add(included[first])
                elif module.startswith(package + '.'):
                    first = module[len(package) + 1:].split('.', 1)[0]
                    if first in included:
                        targets.add(included[first])
    targets.discard(p.name)
    graph[p.name] = sorted(targets)

file_rows = [
    {'name': p.name, 'lines': line_counts[p.name], 'imports': graph[p.name]}
    for p in paths
]

# Build every qualifying prefix member set, then collapse identical sets.
stems = sorted(included)
member_sets = set()
for stem in stems:
    for n in range(4, len(stem) + 1):
        prefix = stem[:n]
        members = frozenset(s for s in stems if s.startswith(prefix))
        if len(members) >= 3:
            member_sets.add(members)

def common_prefix(strings):
    strings = list(strings)
    result = strings[0]
    for value in strings[1:]:
        while not value.startswith(result):
            result = result[:-1]
    return result

prefix_rows = []
for members in member_sets:
    prefix = common_prefix(sorted(members))
    names = sorted(included[s] for s in members)
    prefix_rows.append({
        'prefix': prefix,
        'files': names,
        'lines': sum(line_counts[name] for name in names),
    })
prefix_rows.sort(key=lambda row: row['prefix'])

# Compute each eligible root's transitive closure, including the root once.
tree_rows = []
for root in sorted(graph):
    if len(graph[root]) < 3:
        continue
    seen = {root}
    stack = list(graph[root])
    while stack:
        current = stack.pop()
        if current in seen:
            continue
        seen.add(current)
        stack.extend(graph[current])
    if len(seen) >= 5:
        names = sorted(seen)
        tree_rows.append({
            'root': root,
            'files': names,
            'lines': sum(line_counts[name] for name in names),
        })
tree_rows.sort(key=lambda row: row['root'])

result = {
    'files': file_rows,
    'prefix_clusters': prefix_rows,
    'import_tree_clusters': tree_rows,
}
outfile.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(f'wrote {outfile} ({outfile.stat().st_size} bytes)')
print('files:', len(file_rows), 'prefix clusters:', len(prefix_rows), 'import-tree clusters:', len(tree_rows))
print(outfile.read_text(encoding='utf-8'))

